     1	/**
     2	 * JSON search endpoint used by the command palette.
     3	 *
     4	 * Owner D. The palette hits this route rather than the Server Action because it
     5	 * fires on every keystroke and wants a plain cancellable fetch. Like
     6	 * `searchAction` it asks for every kind and leaves the plan gating to the
     7	 * service, so neither entry point can be the lenient one.
     8	 *
     9	 * Must call (do not reimplement): can, isEnabled
    10	 */
    11	
    12	import { errorResponse, failure } from "@/app/api/_lib/responses";
    13	import { getActor } from "@/lib/actor";
    14	import { isEnabled } from "@/lib/feature-flags";
    15	import { can } from "@/lib/permissions";
    16	import { searchQuerySchema } from "@/schemas/search";
    17	import { buildFlagContext } from "@/server/services/feature-flag-service";
    18	import { getOrganizationSummary } from "@/server/services/organization-service";
    19	import { search } from "@/server/services/search-service";
