    15	const KIND_HEADINGS: Readonly<Record<SearchHit["kind"], string>> = {
    16	  issue: "Issues",
    17	  comment: "Comments",
    18	  project: "Projects",
    19	};
    20	
    21	/** Groups hits by kind while preserving the relevance order inside a kind. */
    22	export function groupHits(
    23	  hits: readonly SearchHit[],
    24	): readonly { kind: SearchHit["kind"]; hits: readonly SearchHit[] }[] {
    25	  const byKind = new Map<SearchHit["kind"], SearchHit[]>();
    26	  for (const hit of hits) {
    27	    const bucket = byKind.get(hit.kind) ?? [];
    28	    bucket.push(hit);
    29	    byKind.set(hit.kind, bucket);
    30	  }
    31	  return [...byKind.entries()].map(([kind, group]) => ({ kind, hits: group }));
    32	}
    33	
    34	export function SearchResults(props: SearchResultsProps): ReactElement | null {
    35	  const { hits, query, onSelect } = props;
