  3	/**
  4	 * Ctrl+K overlay shell; the domain layer supplies the groups.
  5	 *
  6	 * Owner A — design system. Knows nothing about commands: it filters the groups
  7	 * it is handed, keeps a single flat active index across group boundaries (so
  8	 * ArrowDown walks from the last item of one group into the first of the next),
  9	 * and reports the chosen id. Registering shortcuts is `useCommandPalette`'s job.
 10	 */
 11	import { useMemo, useState } from "react";
 12	import type { KeyboardEvent, ReactElement } from "react";
 13	import { cn } from "@/lib/cn";
