 52	export function CommandPalette(props: CommandPaletteProps): ReactElement | null {
 53	  const { open, groups, placeholder = "Search commands…", onClose, onSelect } = props;
 54	
 55	  const [query, setQuery] = useState("");
 56	  const [activeIndex, setActiveIndex] = useState(0);
 57	
 58	  const panelRef = useDismissableLayer<HTMLDivElement>({ open, onDismiss: onClose });
 59	  useScrollLock(open);
 60	
 61	  const { rows, sections } = useMemo(
 62	    () => flattenGroups(groups, query),
 63	    [groups, query],
 64	  );
 65	
 66	  // A fresh open starts from a clean query. Adjusting state during render on an
 67	  // open/closed transition is the documented alternative to an effect here: the
 68	  // reset lands in the same commit as the open, with no extra paint.
 69	  const [wasOpen, setWasOpen] = useState(open);
 70	  if (open !== wasOpen) {
 71	    setWasOpen(open);
 72	    if (open) {
 73	      setQuery("");
 74	      setActiveIndex(0);
 75	    }
 76	  }
 77	
 78	  const choose = (id: string) => {
 79	    onSelect(id);
 80	    onClose();
 81	  };
 82	
 83	  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
 84	    const key = event.key;
 85	    if (isNavKey(key)) {
 86	      event.preventDefault();
 87	      setActiveIndex((index) => moveActiveIndex(index, key, rows.length));
 88	      return;
 89	    }
 90	    if (key === "Enter") {
 91	      event.preventDefault();
 92	      const row = rows[activeIndex];
 93	      if (row) choose(row.item.id);
 94	    }
 95	  };
 96	
 97	  if (!open) return null;
 98	
 99	  return (
100	    <div className={cn(OVERLAY, "flex items-start justify-center p-4 pt-24")}>
101	      <div
102	        ref={panelRef}
103	        role="dialog"
104	        aria-modal="true"
105	        aria-label="Command palette"
106	        onKeyDown={handleKeyDown}
107	        className={cn(SURFACE, "w-full max-w-xl overflow-hidden rounded-lg shadow-2xl")}
108	      >
109	        <input
110	          autoFocus
111	          type="text"
112	          role="combobox"
113	          aria-expanded
114	          aria-controls="command-palette-list"
115	          aria-autocomplete="list"
116	          value={query}
117	          placeholder={placeholder}
118	          onChange={(event) => {
119	            setQuery(event.target.value);
120	            setActiveIndex(0);
121	          }}
122	          className={cn(
123	            "w-full border-b bg-transparent px-4 py-3 text-sm outline-none placeholder:text-black/40",
124	            CONTROL_BORDER,
125	          )}
126	        />
127	
128	        <div id="command-palette-list" role="listbox" className="max-h-80 overflow-y-auto py-1">
129	          {rows.length === 0 ? (
130	            <p className="px-4 py-6 text-center text-xs text-black/45">
131	              No commands match “{query}”
132	            </p>
133	          ) : null}
134	
135	          {sections.map((section) => (
136	            <div key={section.heading} className="py-1">
137	              <p className="px-4 pb-1 text-[10px] font-semibold uppercase tracking-wide text-black/40">
138	                {section.heading}
139	              </p>
140	              {section.rows.map((row) => (
141	                <button
142	                  key={row.item.id}
143	                  type="button"
144	                  role="option"
145	                  aria-selected={row.index === activeIndex}
146	                  tabIndex={-1}
147	                  onMouseEnter={() => setActiveIndex(row.index)}
148	                  onClick={() => choose(row.item.id)}
149	                  className={cn(
150	                    "flex w-full items-center gap-3 px-4 py-2 text-left text-sm",
151	                    row.index === activeIndex && "bg-surface-muted",
152	                  )}
153	                >
154	                  <span className="flex-1 truncate text-black/85 dark:text-white/85">
155	                    {row.item.label}
156	                  </span>
157	                  {row.item.hint !== undefined ? (
158	                    <span className="truncate text-[11px] text-black/45">
159	                      {row.item.hint}
160	                    </span>
161	                  ) : null}
162	                  {row.item.shortcut !== undefined ? (
163	                    <kbd className="rounded border border-black/15 px-1 text-[10px] text-black/55">
164	                      {row.item.shortcut}
165	                    </kbd>
166	                  ) : null}
167	                </button>
168	              ))}
169	            </div>
170	          ))}
171	        </div>
172	      </div>
173	    </div>
174	  );
175	}
