/**
 * The search query language (ADR 0007).
 *
 * This is the one parser: the search dialog uses it to show what it understood
 * and `SearchService` uses it to decide what is actually searched, so the two
 * cannot drift. Free of server-only and React imports for that reason.
 */
import type { ProjectId } from "@/types/common";

export type SearchSubjectKind = "issue" | "comment" | "project";

const KINDS: readonly SearchSubjectKind[] = ["issue", "comment", "project"];

export interface ParsedSearchQuery {
  /** The free-text remainder, with every field token removed. */
  readonly text: string;
  readonly kinds: readonly SearchSubjectKind[];
  readonly projectId: ProjectId | null;
  /** Tokens that looked like syntax but named nothing we know. */
  readonly unknownTokens: readonly string[];
}

export const DEFAULT_SEARCH_KINDS: readonly SearchSubjectKind[] = ["issue"];

/** What the tokens of a query said, before any default is applied. */
interface ScannedSearchQuery {
  readonly text: string;
  /** Kinds named by `kind:` / `in:` tokens; empty when there were none. */
  readonly kindTokens: readonly SearchSubjectKind[];
  readonly projectId: ProjectId | null;
  readonly unknownTokens: readonly string[];
}

/**
 * Splits a query into field tokens and free text.
 *
 * A field token is a whitespace-delimited word of the form `field:value` with
 * a non-empty field. Tokens are only recognised when `advanced` is true;
 * otherwise the whole query is free text and a colon is just a character.
 */
function scanSearchQuery(raw: string, advanced: boolean): ScannedSearchQuery {
  if (!advanced) {
    return {
      text: raw.trim(),
      kindTokens: [],
      projectId: null,
      unknownTokens: [],
    };
  }

  const kinds: SearchSubjectKind[] = [];
  const unknown: string[] = [];
  let projectId: ProjectId | null = null;

  // The free text keeps the words exactly as typed, including the whitespace
  // between two neighbouring words; a removed token leaves a single space.
  let text = "";
  let previousWasTerm = false;

  for (const match of raw.matchAll(/(\s*)(\S+)/g)) {
    const gap = match[1] ?? "";
    const token = match[2] ?? "";

    const separator = token.indexOf(":");
    if (separator <= 0) {
      if (text.length > 0) text += previousWasTerm ? gap : " ";
      text += token;
      previousWasTerm = true;
      continue;
    }
    previousWasTerm = false;

    const field = token.slice(0, separator).toLowerCase();
    const value = token.slice(separator + 1);
    if (value.length === 0) {
      unknown.push(token);
      continue;
    }

    if (field === "kind" || field === "in") {
      const kind = value.toLowerCase().replace(/s$/, "") as SearchSubjectKind;
      if (!KINDS.includes(kind)) unknown.push(token);
      else if (!kinds.includes(kind)) kinds.push(kind);
    } else if (field === "project") {
      projectId = value as ProjectId;
    } else {
      unknown.push(token);
    }
  }

  return { text, kindTokens: kinds, projectId, unknownTokens: unknown };
}

/**
 * @param raw      what the user typed
 * @param advanced whether the `advanced_search` flag is on for this org; when
 *                 false the whole string is treated as free text so a colon in
 *                 a title still finds the title.
 */
export function parseSearchQuery(
  raw: string,
  advanced: boolean,
): ParsedSearchQuery {
  const scanned = scanSearchQuery(raw, advanced);
  return {
    text: scanned.text,
    kinds:
      scanned.kindTokens.length > 0 ? scanned.kindTokens : DEFAULT_SEARCH_KINDS,
    projectId: scanned.projectId,
    unknownTokens: scanned.unknownTokens,
  };
}

/** What a caller of the search service asked for alongside the query. */
export interface SearchRequestScope {
  readonly kinds: readonly SearchSubjectKind[];
  readonly projectId?: ProjectId | undefined;
}

/** What is actually searched once the query and the plan have had their say. */
export interface ResolvedSearchQuery {
  readonly text: string;
  readonly kinds: readonly SearchSubjectKind[];
  readonly projectId: ProjectId | undefined;
}

/**
 * Combines the query with the caller's requested scope (ADR 0007, rules 2–4).
 *
 * With `advanced_search`, `kind:` tokens replace the caller's kinds and a
 * `project:` token replaces the caller's project. Without it nothing in the
 * query is syntax and only issues are searched, whatever the caller asked for.
 */
export function resolveSearchQuery(
  raw: string,
  advanced: boolean,
  requested: SearchRequestScope,
): ResolvedSearchQuery {
  const scanned = scanSearchQuery(raw, advanced);

  if (!advanced) {
    return {
      text: scanned.text,
      kinds: DEFAULT_SEARCH_KINDS,
      projectId: requested.projectId,
    };
  }

  return {
    text: scanned.text,
    kinds: scanned.kindTokens.length > 0 ? scanned.kindTokens : requested.kinds,
    projectId: scanned.projectId ?? requested.projectId,
  };
}

/** A one-line explanation of what the parser understood, for the dialog. */
export function describeQuery(parsed: ParsedSearchQuery): string {
  const parts = [`searching ${parsed.kinds.join(", ")}`];
  if (parsed.projectId !== null) parts.push(`in project ${parsed.projectId}`);
  if (parsed.unknownTokens.length > 0) {
    parts.push(`ignoring ${parsed.unknownTokens.join(", ")}`);
  }
  return parts.join(" · ");
}

