 * for content and a partially-applied write can never be indexed as if it had
 * succeeded.
 */
async function syncDocument(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  switch (subjectKind) {
    case "issue": {
      const issue = await issueRepo.findIssueById(orgId, subjectId as IssueId);
      if (issue && !isArchived(issue)) return indexIssue(orgId, issue);
      break;
    }
    case "comment": {
      const comment = await commentRepo.findCommentById(
        orgId,
        subjectId as CommentId,
      );
      if (comment && !isArchived(comment)) return indexComment(orgId, comment);
      break;
    }
    case "project": {
      const project = await projectRepo.findProjectById(
        orgId,
        subjectId as ProjectId,
      );
      if (project && !isArchived(project)) return indexProject(orgId, project);
      break;
    }
    default:
      // Not a kind the index knows; there is nothing to write or remove.
      return;
  }

  await removeFromIndex(orgId, subjectKind, subjectId);
}

/**
