export async function indexComment(
  orgId: OrgId,
  comment: Comment,
  issueProjectId?: ProjectId,
): Promise<void> {
  const projectId =
    issueProjectId ??
    (await issueRepo.findIssueById(orgId, comment.issueId))?.projectId ??
