start=s.index('/**\n * Keeps the index in step with writes.')
end=s.index('function hrefFor(')
new='''/**
 * Brings one subject's document in line with its row: a live row is
 * (re-)indexed, a row that is archived or no longer exists is taken out of
 * the index. The row is always re-read, so an event payload is never trusted
 * for content and a partially-applied write can never be indexed as if it had
 * succeeded.
 */
async function syncDocument(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  switch (subjectKind) {
    case "issue": {
      const issue = await issueRepo.findIssueById(orgId, subjectId as IssueId);
      if (issue && !isArchived(issue)) return indexIssue(orgId, issue);
      break;
    }
    case "comment": {
      const comment = await commentRepo.findCommentById(
        orgId,
        subjectId as CommentId,
      );
      if (comment && !isArchived(comment)) return indexComment(orgId, comment);
      break;
    }
    case "project": {
      const project = await projectRepo.findProjectById(
        orgId,
        subjectId as ProjectId,
      );
      if (project && !isArchived(project)) return indexProject(orgId, project);
      break;
    }
    default:
      // Not a kind the index knows; there is nothing to write or remove.
      return;
  }

  await removeFromIndex(orgId, subjectKind, subjectId);
}

/**
 * Keeps the index in step with writes. Every handler goes through
 * `syncDocument`, so creation, edits and reindex requests all write the same
 * document for a subject — and none of them can index an archived row.
 */
export function registerSearchListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.created", async (payload) => {
      await syncDocument(payload.orgId, "issue", payload.issueId);
    }),
    subscribe("issue.updated", async (payload) => {
      await syncDocument(payload.orgId, "issue", payload.issueId);
    }),
    subscribe("issue.archived", async (payload) => {
      await removeFromIndex(payload.orgId, "issue", payload.issueId);
    }),
    subscribe("comment.created", async (payload) => {
      await syncDocument(payload.orgId, "comment", payload.commentId);
    }),
    subscribe("comment.deleted", async (payload) => {
      await removeFromIndex(payload.orgId, "comment", payload.commentId);
    }),
    subscribe("project.created", async (payload) => {
      await syncDocument(payload.orgId, "project", payload.projectId);
    }),
    subscribe("project.archived", async (payload) => {
      await removeFromIndex(payload.orgId, "project", payload.projectId);
    }),
    subscribe("search.reindex_requested", async (payload) => {
      await syncDocument(payload.orgId, payload.subjectKind, payload.subjectId);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

