new='''  const debounced = useDebouncedValue(raw);
  const advanced =
    flags.advanced_search === true ||
    isEnabled("advanced_search", { ...ANONYMOUS_FLAG_CONTEXT, orgId });

  // The parse is only what the hint line shows. The server reads the query
  // with the same parser (ADR 0007), so the query is sent as typed and the
  // service decides what it means for this workspace's plan.
  const parsed = useMemo(
    () => parseSearchQuery(debounced, advanced),
    [debounced, advanced],
  );

  const request = debounced.trim();
  const query = parsed.text;
  const searchable = query.length > 0;
  const pending = searchable && results.query !== request;

  useEffect(() => {
    if (!open || !searchable) return;

    let cancelled = false;

    void onSearch({
      orgId,
      q: request,
      kinds: [...parsed.kinds],
      limit: SEARCH_PAGE_SIZE,
    }).then((result) => {
      if (cancelled) return;
      setResults({ query: request, hits: result.ok ? result.data : [] });
    });

    return () => {
      cancelled = true;
    };
    // `parsed` is memoised on the debounced string, so the effect re-fires
    // when the request changes and not on every render or keystroke.
