grep -rn "Field-scoped\|not included in this plan" src tests | head; cat > /tmp/search-check.test.ts <<'EOF'
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { emit } from "@/lib/event-bus";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import * as searchRepo from "@/server/repositories/search-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import { getDb, searchIndex } from "@/server/db";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let ent: Tenant;
let starter: Tenant;
let growth: Tenant;
let detach: () => void;

const q = (t: Tenant, text: string, kinds: any = ["issue", "comment", "project"], extra: any = {}) =>
  searchService.search(t.actors.member, { orgId: t.org.id, q: text, kinds, limit: 25, cursor: null, ...extra });

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
  ent = await createTenant("ent", "enterprise");
  starter = await createTenant("starter", "starter");
  growth = await createTenant("growth", "growth");
});
afterAll(() => { detach(); cleanup(); });

const env = (t: Tenant) => ({ orgId: t.org.id, actorId: null, occurredAt: new Date().toISOString() as never });

describe("scratch", () => {
  it("1 colon on starter", async () => {
    const issue = await issueService.createIssue(starter.actors.member, issueInput(starter.org.id, starter.project.id, { title: "Release 2: hotfix" }));
    const r = await q(starter, "Release 2: hotfix");
    expect(r.items.map((i) => i.id)).toEqual([issue.id]);
    expect((await q(starter, "kind:comment Release")).total).toBe(0);
  });

  it("2/3 tokens on enterprise + comments in project", async () => {
    const issue = await issueService.createIssue(ent.actors.member, issueInput(ent.org.id, ent.project.id, { title: "Deploy pipeline flaky tests" }));
    const comment = await commentService.createComment(ent.actors.member, { orgId: ent.org.id, issueId: issue.id, body: "this is Flaky on deploy", parentId: null, mentionedUserIds: [] });
    expect((await q(ent, "kind:comment flaky", ["issue"])).items.map((i) => [i.kind, i.id])).toEqual([["comment", comment.id]]);
    expect((await q(ent, "in:comments flaky", ["issue"])).total).toBe(1);
    expect((await q(ent, `project:${ent.project.id} deploy`)).total).toBe(2);
    expect((await q(ent, `project:01ARZ3NDEKTSV4RRFFQ69G5FAV deploy`)).total).toBe(0);
    expect((await q(ent, "flaky", ["comment"], { projectId: ent.project.id })).total).toBe(1);
    expect((await q(ent, "label:bug flaky  ", ["issue"])).total).toBe(1);
    // wipe + rebuild
    getDb().delete(searchIndex).run();
    await runSearchReindexJob(ent.org.id);
    expect((await q(ent, "flaky", ["comment"], { projectId: ent.project.id })).total).toBe(1);
    // edit
    await commentService.updateComment(ent.actors.member, { orgId: ent.org.id, commentId: comment.id, body: "now it is Wobbly" });
    expect((await q(ent, "wobbly", ["comment"], { projectId: ent.project.id })).total).toBe(1);
    expect((await q(ent, "flaky", ["comment"])).total).toBe(0);
    // reindex
    getDb().delete(searchIndex).run();
    await emit("search.reindex_requested", { ...env(ent), subjectKind: "comment", subjectId: comment.id });
    await emit("search.reindex_requested", { ...env(ent), subjectKind: "project", subjectId: ent.project.id });
    expect((await q(ent, `project:${ent.project.id} wobbly kind:comment`)).total).toBe(1);
    expect((await q(ent, "platform", ["project"])).total).toBe(1);
    await issueService.archiveIssue(ent.actors.admin, ent.org.id, issue.id);
    await emit("search.reindex_requested", { ...env(ent), subjectKind: "issue", subjectId: issue.id });
    expect((await q(ent, "pipeline", ["issue"])).total).toBe(0);
  });

  it("4 literal", async () => {
    await issueService.createIssue(ent.actors.member, issueInput(ent.org.id, ent.project.id, { title: "Reached 100% coverage" }));
    await issueService.createIssue(ent.actors.member, issueInput(ent.org.id, ent.project.id, { title: "use snake_case here" }));
    await issueService.createIssue(ent.actors.member, issueInput(ent.org.id, ent.project.id, { title: "use snake case there" }));
    await issueService.createIssue(ent.actors.member, issueInput(ent.org.id, ent.project.id, { title: "path C:\\temp ÉCLAIR" }));
    expect((await q(ent, "100%", ["issue"])).total).toBe(1);
    expect((await q(ent, "snake_case", ["issue"])).total).toBe(1);
    expect((await q(ent, "SNAKE_CASE", ["issue"])).total).toBe(1);
    expect((await q(ent, "\\temp", ["issue"])).total).toBe(1);
    expect((await q(ent, "éclair", ["issue"])).total).toBe(1);
    expect((await q(ent, "%", ["issue"])).total).toBe(1);
    expect((await q(ent, "_", ["issue"])).total).toBe(1);
  });

  it("5 growth issues only, override", async () => {
    const issue = await issueService.createIssue(growth.actors.member, issueInput(growth.org.id, growth.project.id, { title: "Marker thing" }));
    await commentService.createComment(growth.actors.member, { orgId: growth.org.id, issueId: issue.id, body: "Marker comment", parentId: null, mentionedUserIds: [] });
    const r = await q(growth, "marker");
    expect(r.total).toBe(1);
    expect(r.items.every((i) => i.kind === "issue")).toBe(true);
    expect((await q(growth, "marker", ["comment"])).items.map((i) => i.kind)).toEqual(["issue"]);
    await orgRepo.updateOrg(growth.org.id, { orgId: growth.org.id, settings: { enabledFlagOverrides: ["advanced_search"] } } as never);
    expect((await q(growth, "marker")).total).toBe(2);
    expect((await q(growth, "kind:comment marker", ["issue"])).total).toBe(1);
  });
});
EOF
